<script setup lang="ts">import type {CapabilityView} from '../types';defineProps<{used:string[];catalog:CapabilityView[]}>();</script>
<template><section class="ai-capabilities"><h4>Capabilities used by this draft</h4><p v-if="!used.length" class="muted">No capability calls detected.</p><ul><li v-for="name in used" :key="name"><template v-for="cap in catalog.filter(item=>item.name===name).slice(0,1)" :key="cap.name"><span>{{cap.riskLevel==='READ'?'✓':'!'}}</span> <code>{{name}}</code> <small :class="cap.riskLevel==='READ'?'risk-read':'risk-write'">{{cap.riskLevel}}{{cap.riskLevel==='READ'?'':' (disabled in preview)'}}</small></template><template v-if="!catalog.some(item=>item.name===name)"><span>?</span> <code>{{name}}</code> <small class="risk-write">UNKNOWN</small></template></li></ul></section></template>
